import type { MedusaRequest, MedusaResponse } from "@medusajs/framework/http"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"
const esc=(v:any)=>String(v??"").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]||c))
const actorId=(req:MedusaRequest)=>(req as any).auth_context?.actor_id||(req as any).auth_context?.auth_identity_id
async function sellerId(req:MedusaRequest,actor:string){try{const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:"seller_member",fields:["seller.id"],filters:{member_id:actor},pagination:{take:1}});return data?.[0]?.seller?.id||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller=await sellerId(req,actor);const spike=req.scope.resolve("spike") as any;const query=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await query.graph({entity:"order",fields:["id","display_id","email","shipping_address.*","items.id","items.product_id","items.product_title","items.variant_title","items.quantity","items.metadata"],filters:{id:req.params.id},pagination:{take:1}});const o=data?.[0];if(!o)return res.status(404).json({message:"Order not found"});const pids=[...new Set((o.items||[]).map((i:any)=>i.product_id).filter(Boolean))];const links=pids.length?await spike.listSpikeProductDeliveries({product_id:pids},{take:500}):[];const owned=new Set(links.filter((x:any)=>!seller||x.seller_id===seller).map((x:any)=>String(x.product_id)));const items=(o.items||[]).filter((i:any)=>owned.has(String(i.product_id)));if(!items.length)return res.status(403).json({message:"لا توجد عناصر لهذا المتجر في الطلب"});const a=o.shipping_address||{};const groups=new Map<string,any>();for(const i of items){const m=i.metadata||{};const id=String(m.spike_delivery_office_id||"unassigned");if(!groups.has(id))groups.set(id,{name:m.spike_delivery_office_name||"مكتب التوصيل",phone:m.spike_delivery_office_phone||"",items:[]});groups.get(id).items.push(i)}const sections=[...groups.values()].map((g:any)=>`<h2>${esc(g.name)}</h2><p><b>رقم المكتب:</b> ${esc(g.phone||"—")}</p><table><tr><th>المنتج</th><th>الكمية</th></tr>${g.items.map((i:any)=>`<tr><td>${esc(i.product_title||i.variant_title||i.product_id)}</td><td>${esc(i.quantity)}</td></tr>`).join("")}</table>`).join("");const html=`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;direction:rtl;padding:28px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:8px;text-align:right}.box{border:1px solid #bbb;padding:12px;margin:12px 0}</style></head><body><h1>Spike — طلب شحن #${esc(o.display_id||o.id)}</h1><div class="box"><p><b>العميل:</b> ${esc([a.first_name,a.last_name].filter(Boolean).join(" ")||o.email||"—")}</p><p><b>الهاتف:</b> ${esc(a.phone||"—")}</p><p><b>عنوان التوصيل:</b> ${esc([a.city,a.province,a.address_1,a.address_2].filter(Boolean).join(" - "))}</p></div>${sections}</body></html>`;res.setHeader("Content-Type","application/msword; charset=utf-8");res.setHeader("Content-Disposition",`attachment; filename="spike-order-${o.display_id||o.id}.doc"`);res.send(html)}
